using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Library.Web.Models;using Library.Web.Services;
namespace Library.Web.Pages.Members;
public sealed class IndexModel:PageModel{private readonly LibraryStore _store;public IReadOnlyList<Member> Members{get;private set;}=[];[BindProperty]public Member NewMember{get;set;}=new();public string? ErrorMessage{get;private set;}public IndexModel(LibraryStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(string.IsNullOrWhiteSpace(NewMember.MemberNumber)||string.IsNullOrWhiteSpace(NewMember.FullName)){ErrorMessage="Member number and full name are required.";Load();return Page();}try{_store.AddMember(NewMember);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load()=>Members=_store.Members;}
